HANDLE CreateEventA(
  LPSECURITY_ATTRIBUTES lpEventAttributes,
  BOOL bManualReset,
  BOOL bInitialState,
  LPCSTR lpName
);

example:
HANDLE ev = CreateEventA(NULL, FALSE, FALSE, NULL);
if (!ev) return 1;
SetEvent(ev);
WaitForSingleObject(ev, INFINITE);
CloseHandle(ev);

sig:
HANDLE OpenEventA(
  DWORD dwDesiredAccess,
  BOOL bInheritHandle,
  LPCSTR lpName
);

example:
HANDLE ev = OpenEventA(EVENT_MODIFY_STATE, FALSE, "my_evt");
if (!ev) { printf("%lu\n", GetLastError()); return 1; }
SetEvent(ev);
CloseHandle(ev);

HANDLE ev = CreateEventA(NULL, FALSE, FALSE, NULL);
SetEvent(ev);
WaitForSingleObject(ev, 1000);  // 立即返回 WAIT_OBJECT_0
CloseHandle(ev);

HANDLE ev = CreateEventA(NULL, TRUE, FALSE, NULL);
SetEvent(ev);
ResetEvent(ev);  // 回到无信号
CloseHandle(ev);

